CREATE DATABASE IF NOT EXISTS kujoin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kujoin;
CREATE TABLE events (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,event_date DATE NOT NULL,location VARCHAR(255) NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE participant_types (id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,name VARCHAR(255) NOT NULL,requires_org_name BOOLEAN NOT NULL DEFAULT FALSE,requires_status_field BOOLEAN NOT NULL DEFAULT FALSE,sort_order INT NOT NULL DEFAULT 0,CONSTRAINT fk_type_event FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE time_slots (id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,slot_time VARCHAR(20) NOT NULL,title VARCHAR(255) NOT NULL,location VARCHAR(255) NULL,sort_order INT NOT NULL DEFAULT 0,CONSTRAINT fk_slot_event FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE registrations (id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,participant_type_id INT NOT NULL,org_name VARCHAR(255) NULL,representative_name VARCHAR(255) NULL,position VARCHAR(255) NULL,companion_count INT NOT NULL DEFAULT 0,phone VARCHAR(20) NULL,full_name VARCHAR(255) NOT NULL,status ENUM('ผู้บริหาร','อาจารย์อาวุโส_ผู้เกษียณ','อาจารย์','บุคลากร') NULL,department VARCHAR(255) NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_registration_event FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,CONSTRAINT fk_registration_type FOREIGN KEY(participant_type_id) REFERENCES participant_types(id),INDEX idx_event_created(event_id,created_at)) ENGINE=InnoDB;
CREATE TABLE registration_time_slots (registration_id INT NOT NULL,time_slot_id INT NOT NULL,PRIMARY KEY(registration_id,time_slot_id),CONSTRAINT fk_rts_registration FOREIGN KEY(registration_id) REFERENCES registrations(id) ON DELETE CASCADE,CONSTRAINT fk_rts_slot FOREIGN KEY(time_slot_id) REFERENCES time_slots(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE admin_users (id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','staff') NOT NULL DEFAULT 'staff',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
